-- Importa para o banco o conteúdo que estava fixo no código, para ser editado pelo painel.
-- Artistas e lançamentos já cadastrados mantêm o id, então os links existentes continuam valendo.

insert into public.artists (id, name, genre, bio, short_bio, image_url, instagram, spotify, youtube, photo_position, followers, songs, videos, legacy_id, order_index)
values (coalesce((select id from public.artists where name = 'Alex Lúcio'), gen_random_uuid()), 'Alex Lúcio', 'Gospel/CCM', 'Alex Lúcio nasceu e foi criado em um lar cristão, tendo suas raízes firmadas desde cedo na igreja. Vindo de uma infância simples e humilde, ele é o terceiro de cinco irmãos. Desde pequeno, Alex se destacou nos estudos, sempre dedicado e esforçado, alcançando notas máximas em todas as matérias. Aos 11 anos, seu talento acadêmico lhe rendeu o terceiro lugar em uma oficina de matemática, um momento que marcou sua trajetória escolar.

Com a mãe precisando trabalhar fora para sustentar a família, Alex aprendeu desde cedo o valor do esforço e da fé. Na adolescência, ele descobriu sua vocação para a música, começando então a compor e cantar com o coração voltado sempre para Deus. Seu amor pela música se transformou em uma missão maior: hoje, ele realiza um importante trabalho de evangelização no Calçadão de Campo Grande, levando esperança e a Palavra de Deus a muitas vidas, onde já ganhou centenas de almas pra Jesus.

Alex é membro ativo da Igreja Assembleia de Deus em Campo Grande, onde encontra inspiração espiritual e apoio para continuar sua caminhada. Sua trajetória é marcada por dedicação, talento e fé, e seu objetivo é sempre ser um instrumento nas mãos de Deus para tocar corações e transformar vidas através da música.', 'Alex é membro ativo da Igreja Assembleia de Deus em Campo Grande, onde encontra inspiração espiritual e apoio para continuar sua caminhada. Sua trajetória é marcada por dedicação, talento e fé, e seu objetivo é sempre ser um instrumento nas mãos de Deus para tocar corações e transformar vidas através da música.', '/artistas/alex-lucio/IMG_3735.jpg', 'https://www.instagram.com/alexlucio.ofc/', 'https://open.spotify.com/artist/2xX3xodC7zA5u2xygCWzuP', 'https://www.youtube.com/watch?v=Bqc6B5LzTN0&list=RDBqc6B5LzTN0&start_radio=1', '50% 50%', '{"spotify":"2.6M"}'::jsonb, '[{"title":"O Fogo Arderá - Ao Vivo","album":"","plays":"58.6M"},{"title":"Buscar-Me-Eis e Me Achareis - Ao Vivo","album":"","plays":"14.5M"},{"title":"O Fogo Arderá","album":"","plays":"9.1M"},{"title":"Salva-Vidas","album":"","plays":"4.3M"},{"title":"Sempre Estive Aqui","album":"Single","plays":"1.0M"}]'::jsonb, '[{"title":"O Fogo Arderá - Ao Vivo","url":"https://www.youtube.com/watch?v=Bqc6B5LzTN0&list=RDBqc6B5LzTN0&start_radio=1"},{"title":"Salva-Vidas - Ao Vivo","url":"https://www.youtube.com/watch?v=bdLeReQbtgY&list=PLDrdTf3Y6voff928gg2qErmcgMV_surVw"}]'::jsonb, 1, 1)
