insert into public.artists (id, name, genre, bio, short_bio, image_url, instagram, spotify, youtube, photo_position, followers, songs, videos, legacy_id, order_index)
values (coalesce((select id from public.artists where name = 'Na Graça'), gen_random_uuid()), 'Na Graça', 'Gospel/CCM', 'Na Graça é um ministério de louvor que nasceu com o propósito de conduzir a igreja a uma experiência profunda com Deus através da adoração. Com canções congregacionais e mensagens centradas na fé, o grupo tem se destacado por suas ministrações ao vivo, marcadas por simplicidade, unidade e forte presença de Deus.

Entre suas faixas mais conhecidas estão “A Fé (Ao Vivo)”, “Ele Te Chamou (Ao Vivo)” e “Louva Na Graça (Ao Vivo)”, que têm alcançado milhares de ouvintes nas plataformas digitais. O grupo segue avançando com novos projetos e gravações ao vivo, sempre com o foco em espalhar a graça e o amor de Cristo por meio da música.', 'Grupo de adoração que leva mensagens de fé e esperança através de ministrações ao vivo e canções marcadas pela presença de Deus.', '/artistas/na graca/na graca.png', 'https://www.instagram.com/nagracaoficial/', 'https://open.spotify.com/intl-pt/artist/7pmvHrURMH0OqDcXXQiuYX', 'https://www.youtube.com/watch?v=g89eBxkG-Aw&list=RDg89eBxkG-Aw&start_radio=1', '75% 50%', '{"spotify":"55,5K"}'::jsonb, '[{"title":"A Fé - Ao Vivo","album":"A Fé (Ao Vivo)","plays":"679.8K"},{"title":"Ele Te Chamou - Ao Vivo","album":"Ele Te Chamou (Ao Vivo)","plays":"67.1K"},{"title":"Louva Na Graça - Ao Vivo","album":"Louva Na Graça (Ao Vivo)","plays":"16.7K"}]'::jsonb, '[{"title":"A FÉ - AO VIVO","url":"https://www.youtube.com/watch?v=g89eBxkG-Aw&list=RDg89eBxkG-Aw&start_radio=1"},{"title":"LOUVA NA GRAÇA","url":"https://www.youtube.com/watch?v=5bvgSlZamBo&list=RD5bvgSlZamBo&start_radio=1"}]'::jsonb, 10, 2)
