insert into public.artists (id, name, genre, bio, short_bio, image_url, instagram, spotify, youtube, photo_position, followers, songs, videos, legacy_id, order_index)
values (coalesce((select id from public.artists where name = 'No Santuário'), gen_random_uuid()), 'No Santuário', 'Gospel/CCM', 'Com 13 anos de carreira ministerial, álbuns, EPs e ministrações por todo o Brasil, EUA e Europa, o ministério No Santuário (Pr. Israel Leonardo e Raphaela Carvalho) dedica-se a proclamar o evangelho através da adoração e da pregação da Palavra de Deus. Recentemente lançaram seu primeiro DVD com canções inéditas e uma nova versão de “Final Feliz”, além de projetos como “Ele Fará”, “Teus Átrios” e “Haja o que Houver (Ao Vivo)”.

Com letras bíblicas e forte ênfase na presença de Deus, No Santuário se tornou referência na adoração congregacional, convidando a igreja a viver uma jornada de fé, esperança e restauração em cada canção.', 'Com 13 anos de carreira ministerial, álbuns, EPs e ministrações por todo o Brasil, EUA e Europa, o ministério No Santuário (Pr. Israel Leonardo e Raphaela Carvalho) dedica-se a proclamar o evangelho através da adoração e da pregação da Palavra de Deus. Com letras bíblicas e forte ênfase na presença de Deus, No Santuário se tornou referência na adoração congregacional, convidando a igreja a viver uma jornada de fé, esperança e restauração em cada canção.', '/artistas/no%20santuario/IMG_0090.jpg', 'https://www.instagram.com/nosantuario/', 'https://open.spotify.com/intl-pt/artist/3qkhpijMzbtVFexHZTNoai', 'https://www.youtube.com/watch?v=XWBgmBsxkk4&list=RDXWBgmBsxkk4&start_radio=1', '50% 28%', '{"spotify":"31,3K"}'::jsonb, '[{"title":"Ele Fará","album":"Ele Fará","plays":"99.7K"},{"title":"Teus Átrios","album":"Teus Átrios","plays":"44.1K"},{"title":"Haja o que Houver - Ao Vivo","album":"Haja o que Houver (Ao Vivo)","plays":"33.8K"},{"title":"Tu És o Cristo (I Call You Jesus)","album":"Single","plays":"39.0K"}]'::jsonb, '[{"title":"FINAL FELIZ - AO VIVO","url":"https://www.youtube.com/watch?v=XWBgmBsxkk4&list=RDXWBgmBsxkk4&start_radio=1"},{"title":"HAJA O QUE HOUVER AO VIVO","url":"https://www.youtube.com/watch?v=qv7MCnmsoN0"}]'::jsonb, 11, 3)
