insert into public.artists (id, name, genre, bio, short_bio, image_url, instagram, spotify, youtube, photo_position, followers, songs, videos, legacy_id, order_index)
values (coalesce((select id from public.artists where name = 'Maria Pita'), gen_random_uuid()), 'Maria Pita', 'Gospel/CCM', 'Maria Pita é uma cantora gospel brasileira que carrega em suas canções mensagens de esperança, cura e rendição aos pés de Jesus. Com uma voz doce e firme, suas ministrações convidam a igreja a confiar na fidelidade de Deus em meio às lutas e processos.

Seu ministério tem alcançado diferentes gerações, sempre com o desejo de apontar para Cristo e gerar um ambiente de adoração profunda e sincera.', 'Cantora gospel que traz mensagens de esperança, fé e restauração, com um estilo de adoração sensível e intenso.', '/artistas/maria-pita/IMG_4240.jpg', 'https://www.instagram.com/mariapitacantora_/', 'https://open.spotify.com/intl-pt/artist/7fw7DfkvI0fMyEKfOw0k6n', 'https://www.youtube.com/watch?v=mb7rskqf1A4&list=RDEMzFMowVXry3q4Od_yFQGfxw&index=3', '50% 50%', '{}'::jsonb, '[]'::jsonb, '[{"title":"SE LEVANTE","url":"https://www.youtube.com/watch?v=mb7rskqf1A4&list=RDEMzFMowVXry3q4Od_yFQGfxw&index=3"},{"title":"Maria Pita e Samuel Messias - SOU TEU PAI","url":"https://www.youtube.com/watch?v=aioMdIBKvt8&list=RDEMzFMowVXry3q4Od_yFQGfxw&index=2"}]'::jsonb, 15, 4)
