insert into public.artists (id, name, genre, bio, short_bio, image_url, instagram, spotify, youtube, photo_position, followers, songs, videos, legacy_id, order_index)
values (coalesce((select id from public.artists where name = 'Nicole Lavinia'), gen_random_uuid()), 'Nicole Lavinia', 'Gospel/CCM', 'Nicole Lavinia é uma jovem cantora gospel brasileira que tem se destacado com canções que falam sobre rendição, santidade e intimidade com Deus. Com uma voz doce e marcante, suas ministrações carregam mensagens de esperança e encorajamento para uma geração que deseja viver os propósitos de Cristo.

Através de suas redes sociais e agendas em igrejas e eventos, Nicole tem alcançado novos públicos, sempre com o desejo de conduzir pessoas a um encontro real com Jesus e a uma vida de adoração genuína.', 'Cantora gospel que tem se destacado entre a nova geração de adoradores, com canções que falam de intimidade com Deus e entrega total.', '/artistas/nicole-lavinia/IMG_3996.jpg', 'https://www.instagram.com/nicolelaviniaoficial_/', 'https://open.spotify.com/intl-pt/track/0AayU24085eVhLhbk27sTE', 'https://www.youtube.com/watch?v=vpi33yUn1Zc&list=RDvpi33yUn1Zc&start_radio=1', '50% 30%', '{}'::jsonb, '[]'::jsonb, '[{"title":"SERVO DO CENTURIÃO - AO VIVO","url":"https://www.youtube.com/watch?v=vpi33yUn1Zc&list=RDvpi33yUn1Zc&start_radio=1"}]'::jsonb, 14, 6)
