on conflict (id) do update set name = excluded.name, genre = excluded.genre, bio = excluded.bio, short_bio = excluded.short_bio, image_url = excluded.image_url, instagram = excluded.instagram, spotify = excluded.spotify, youtube = excluded.youtube, photo_position = excluded.photo_position, followers = excluded.followers, songs = excluded.songs, videos = excluded.videos, legacy_id = excluded.legacy_id, order_index = excluded.order_index;

