insert into public.site_settings (key, value) values
  ('about_page', '{"intro":"Conheça a Céu Music e nossa paixão por transformar sonhos em realidade através da música","story":"Somos uma gravadora cristã independente que acredita no poder transformador da música para tocar corações e transformar vidas. Nossa missão é descobrir e desenvolver talentos que levam mensagens de fé, esperança e amor através de produções musicais de excelência. Com tecnologia de ponta, equipe profissional e paixão pelo que fazemos, transformamos sonhos em realidade e levamos a música dos nossos artistas para o mundo inteiro.","mission_title":"Transformar sonhos em realidade","mission_text":"A Céu Music nasceu com o propósito de ser uma plataforma que descobre, desenvolve e promove talentos musicais cristãos. Acreditamos que cada artista tem uma voz única e uma mensagem poderosa para compartilhar com o mundo.\n\nNossa missão vai além de simplesmente produzir música. Queremos criar uma comunidade onde artistas possam crescer, se desenvolver e alcançar seu potencial máximo, sempre mantendo o foco em levar mensagens de fé, esperança e amor através da música.","card_title":"Música com propósito","card_text":"Cada produção nossa carrega uma mensagem de transformação e esperança, criada com excelência e paixão.","values_title":"O que nos move","values_text":"Os valores que guiam cada decisão e cada produção da Céu Music","values":[{"icon":"ri-heart-3-fill","title":"Fé e propósito","description":"Acreditamos no poder transformador da música para tocar corações e transformar vidas através de mensagens de fé e esperança."},{"icon":"ri-star-fill","title":"Excelência","description":"Buscamos sempre a excelência em nossas produções, utilizando tecnologia de ponta e equipe profissional para entregar o melhor resultado."},{"icon":"ri-team-fill","title":"Comunidade","description":"Valorizamos o relacionamento e o trabalho em equipe, criando uma família unida em torno da música e da missão de levar esperança ao mundo."},{"icon":"ri-lightbulb-fill","title":"Inovação","description":"Estamos sempre em busca de novas formas de expressar a arte e alcançar pessoas, utilizando as melhores ferramentas e tecnologias disponíveis."}],"vision_title":"O futuro que construímos","vision_text":"Sonhamos em ser referência nacional e internacional na produção de música cristã de qualidade, reconhecida pela excelência técnica, pela profundidade das mensagens e pelo impacto transformador em vidas.\n\nQueremos continuar descobrindo novos talentos, expandindo nosso catálogo e alcançando cada vez mais pessoas com mensagens de fé, esperança e amor através da música que produzimos."}'::jsonb),
  ('footer_text', '"Gravadora musical independente dedicada a descobrir e promover talentos únicos. Transformando sonhos em realidade através da música."'::jsonb),
  ('contact_subjects', '["Parceria Comercial","Quero ser artista","Assessoria de Imprensa","Contratação para Evento","Outro"]'::jsonb),
  ('page_background', '"/artistas/ceu-music/IMG_2279-2.jpg"'::jsonb),
  ('legal', '{"legal_name":"","cnpj":"","dpo_name":""}'::jsonb)
on conflict (key) do update set value = excluded.value, updated_at = now();

-- O e-mail vigente é o do Gmail; o banco ainda tinha o endereço anterior.
update public.contact_info set value = 'ceumusicbrasil@gmail.com' where type = 'email';

-- Vídeos de exemplo do conteúdo inicial não devem ir ao ar.
update public.hero_videos set video_url = null where video_url like '%commondatastorage.googleapis.com%';

-- Mesmo nome de artista em todo o site.
update public.hero_videos set artist = 'Alex Lúcio' where artist = 'Alexsander Lúcio';
